DO $$BEGIN IF EXISTS(SELECT 1 FROM auth.users WHERE id IN('00000000-0062-4000-8000-000000000001','00000000-0062-4000-8000-000000000002')) THEN RAISE EXCEPTION 'synthetic_actor_collision';END IF;END$$;
INSERT INTO auth.users(id,email,role,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data) SELECT ('00000000-0062-4000-8000-'||lpad(n::text,12,'0'))::uuid,'sitov-epoch62-'||n||'@example.test','authenticated',now(),now(),now(),'{"provider":"email","providers":["email"]}',jsonb_build_object('display_name','Sitov Academy synthetic Paul','native_language','de','ui_language','en') FROM generate_series(1,2)n;
UPDATE public.profiles SET role='teacher' WHERE id='00000000-0062-4000-8000-000000000002';
INSERT INTO public.student_level_access(auth_user_id,level) VALUES('00000000-0062-4000-8000-000000000001','A1.1') ON CONFLICT DO NOTHING;
INSERT INTO sitov_access_private.students(student_id,vip_enabled) VALUES('00000000-0062-4000-8000-000000000001',true) ON CONFLICT(student_id)DO UPDATE SET vip_enabled=true;
INSERT INTO public.path_interventions(auth_user_id,unit_id,action,created_by) SELECT '00000000-0062-4000-8000-000000000001',id,'unlock','00000000-0062-4000-8000-000000000002' FROM public.learning_units WHERE path_source_id='sitov-s3-epoch62';
CREATE TEMP TABLE sitov62_rpc(label text primary key,response jsonb);
GRANT ALL ON sitov62_rpc TO authenticated;CREATE TEMP TABLE sitov62_ids AS SELECT n.id,n.kind FROM public.path_nodes n JOIN public.learning_units u ON u.id=n.unit_id WHERE u.path_source_id='sitov-s3-epoch62';GRANT SELECT ON sitov62_ids TO authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0062-4000-8000-000000000001',true),set_config('request.jwt.claims','{"sub":"00000000-0062-4000-8000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
INSERT INTO sitov62_rpc SELECT 'practice_start',public.start_path_node(id,'en',false) FROM sitov62_ids WHERE kind='practice';
RESET ROLE;
TABLE sitov62_rpc;SELECT pg_temp.sitov61_assert('practice_rpc_started',NOT((SELECT response FROM sitov62_rpc WHERE label='practice_start')?'error'));
INSERT INTO public.path_node_progress(auth_user_id,node_id,status,completed_at) SELECT '00000000-0062-4000-8000-000000000001',n.id,'completed',now() FROM public.path_nodes n JOIN public.learning_units u ON u.id=n.unit_id WHERE u.path_source_id='sitov-s3-epoch62' AND n.kind IN('practice','review') ON CONFLICT(auth_user_id,node_id)DO UPDATE SET status='completed';
SET LOCAL ROLE authenticated;
INSERT INTO sitov62_rpc SELECT 'test_start',public.start_path_test(id,'en') FROM sitov62_ids WHERE kind='test';
RESET ROLE;
SELECT pg_temp.sitov61_assert('test_rpc_started',NOT((SELECT response FROM sitov62_rpc WHERE label='test_start')?'error'));
CREATE TEMP TABLE sitov61_payload AS SELECT path_private.sitov_revision_projection('00000000-0061-4000-8000-000000000001') old;
ALTER TABLE sitov61_payload ADD COLUMN items jsonb;
UPDATE sitov61_payload SET items=jsonb_build_array(jsonb_build_object('id',old->'id','expected_hash',path_private.sitov_revision_hash(old),'after',jsonb_set(jsonb_set(old,'{content,correct_answer}','"übt"'),'{content,accepted_answers}','["übt"]'),'review',jsonb_build_object('approved',true,'reviewer','sitov-synthetic-reviewer','evidence_uri','catalog:sitov-synthetic','before_hash',path_private.sitov_revision_hash(old),'after_hash',path_private.sitov_revision_hash(jsonb_set(jsonb_set(old,'{content,correct_answer}','"übt"'),'{content,accepted_answers}','["übt"]')))));
GRANT SELECT ON sitov61_payload TO service_role;GRANT ALL ON sitov61_checks TO service_role;

SELECT pg_temp.sitov61_assert('private_api_helpers_denied',NOT has_function_privilege('authenticated','path_private.sitov_revision_projection(uuid)','EXECUTE') AND NOT has_function_privilege('service_role','path_private.sitov_revision_projection(uuid)','EXECUTE'));
