CREATE FUNCTION pg_temp.sitov62_deferred(command text) RETURNS void LANGUAGE plpgsql AS $$BEGIN
 BEGIN EXECUTE command;SET CONSTRAINTS ALL IMMEDIATE;EXCEPTION WHEN SQLSTATE '40001' THEN RETURN;WHEN foreign_key_violation THEN RETURN;WHEN check_violation THEN IF SQLERRM='invalid_path_node' THEN RETURN;END IF;RAISE;END;
 RAISE EXCEPTION 'expected_deferred_conflict_missing:%',command;
END$$;
