CREATE TEMP TABLE sitov62_test_revision AS SELECT jsonb_build_array(jsonb_build_object('id',old->'id','expected_hash',path_private.sitov_revision_hash(old),'after',candidate,'review',jsonb_build_object('approved',true,'reviewer','synthetic','evidence_uri','catalog:synthetic','before_hash',path_private.sitov_revision_hash(old),'after_hash',path_private.sitov_revision_hash(candidate)))) items FROM (SELECT old,jsonb_set(jsonb_set(old,'{content,correct_answer}','"übt"'),'{content,accepted_answers}','["übt"]') candidate FROM (SELECT path_private.sitov_revision_projection((response#>>'{exercises,0,id}')::uuid) old FROM sitov62_rpc WHERE label='test_start') a) b;
GRANT SELECT ON sitov62_test_revision TO service_role;
SET LOCAL ROLE service_role;
SELECT public.sitov_revise_path_content('00000000-0062-4000-8000-000000002005',items) FROM sitov62_test_revision;
RESET ROLE;
SET LOCAL ROLE authenticated;
INSERT INTO sitov62_rpc SELECT 'practice_answer',public.submit_path_answer((response->>'run_id')::uuid,'00000000-0061-4000-8000-000000000001','{"text":"lernt"}','00000000-0062-4000-8000-000000002001','en') FROM sitov62_rpc WHERE label='practice_start';
INSERT INTO sitov62_rpc SELECT 'test_answer',public.submit_path_test_answer((response->>'attempt_id')::uuid,(response#>>'{exercises,0,id}')::uuid,'{"text":"lernt"}') FROM sitov62_rpc WHERE label='test_start';
INSERT INTO sitov62_rpc SELECT 'test_finish',public.finish_path_test((response->>'attempt_id')::uuid,'en') FROM sitov62_rpc WHERE label='test_start';
RESET ROLE;
SELECT pg_temp.sitov61_assert('old_practice_rpc_answer_snapshot',(SELECT response#>>'{grade,status}'='EXACT' FROM sitov62_rpc WHERE label='practice_answer'));
SELECT pg_temp.sitov61_assert('old_test_rpc_finish',(SELECT (response->>'percentage')::numeric=100 AND response->>'passed'='true' FROM sitov62_rpc WHERE label='test_finish'));
SELECT pg_temp.sitov61_assert('old_test_review_contains_frozen_answer',(SELECT response#>>'{answers,0,content,text_before}'='Paul ' FROM sitov62_rpc WHERE label='test_finish'));

SELECT pg_temp.sitov61_assert('frozen_help_retained',path_private.present((SELECT old FROM sitov61_payload),'en')->'translation' IS NOT NULL);
SELECT pg_temp.sitov61_assert('oldhelp_not_borrowed',NOT(path_private.present((SELECT old-'translations' FROM sitov61_payload),'en')?'translation'));
SELECT pg_temp.sitov61_error('UPDATE path_private.sitov_content_revisions SET actor_role=actor_role','sitov_revision_immutable');
SELECT pg_temp.sitov61_error('TRUNCATE path_private.sitov_content_revision_receipts','sitov_revision_immutable');
GRANT EXECUTE ON FUNCTION pg_temp.sitov61_error(text,text) TO anon;
SET LOCAL ROLE anon;
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(gen_random_uuid(),''[]'')','permission denied');
RESET ROLE;
SELECT pg_temp.sitov61_assert('anon_api_denied',true);
SELECT set_config('request.jwt.claim.sub','00000000-0062-4000-8000-000000000002',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(gen_random_uuid(),''[]'')','permission denied');
RESET ROLE;
SELECT pg_temp.sitov61_assert('teacher_direct_api_denied',true);

SELECT set_config('request.jwt.claim.sub','00000000-0062-4000-8000-000000000001',true);
SET LOCAL ROLE authenticated;
INSERT INTO sitov62_rpc SELECT 'M_old_practice_resume',public.start_path_node((SELECT node_id FROM public.path_practice_runs WHERE id=(response->>'run_id')::uuid),'en',false) FROM sitov62_rpc WHERE label='practice_start';
INSERT INTO sitov62_rpc SELECT 'M_old_test_review',public.get_path_test_review((SELECT node_id FROM public.path_test_attempts WHERE id=(response->>'attempt_id')::uuid),'en') FROM sitov62_rpc WHERE label='test_start';
RESET ROLE;
SELECT pg_temp.sitov61_assert('M_old_practice_resume_id',(SELECT r.response->>'run_id'=s.response->>'run_id' FROM sitov62_rpc r JOIN sitov62_rpc s ON s.label='practice_start' WHERE r.label='M_old_practice_resume'));
SELECT pg_temp.sitov61_assert('M_old_test_review_pass',(SELECT response->>'passed'='true' AND (response->>'percentage')::numeric=100 FROM sitov62_rpc WHERE label='M_old_test_review'));
