FROM(SELECT old,jsonb_set(jsonb_set(old,'{content,correct_answer}','"übt"'),'{content,accepted_answers}','["übt"]')candidate FROM(SELECT path_private.sitov_revision_projection('00000000-0061-4000-8000-000000000002')old)a)b;
