UNION ALL SELECT 'progress',to_jsonb(x) FROM public.path_node_progress x WHERE auth_user_id='00000000-0062-4000-8000-000000000001'
UNION ALL SELECT 'test',to_jsonb(x) FROM public.path_test_attempts x WHERE auth_user_id='00000000-0062-4000-8000-000000000001'
UNION ALL SELECT 'answer',to_jsonb(x) FROM public.path_test_answers x WHERE attempt_id IN(SELECT id FROM public.path_test_attempts WHERE auth_user_id='00000000-0062-4000-8000-000000000001')
UNION ALL SELECT 'receipt',to_jsonb(x) FROM path_private.answer_receipts x WHERE run_id IN(SELECT id FROM public.path_practice_runs WHERE auth_user_id='00000000-0062-4000-8000-000000000001');
CREATE TEMP TABLE sitov63_old_snapshots AS SELECT to_jsonb(i) row FROM path_private.practice_items i UNION ALL SELECT to_jsonb(i) FROM path_private.test_items i;
INSERT INTO public.path_nodes(id,unit_id,source_id,kind,sort_order,title,topic,merkkarte,goals,is_active)
SELECT ('00000000-0064-4000-8000-'||lpad(n::text,12,'0'))::uuid,p.unit_id,'sitov-card-case-'||n,'practice',100+n,'Sitov Academy Paul',p.topic,jsonb_set(p.merkkarte,'{card}',to_jsonb(CASE WHEN n=1 THEN 'sitov-card-inactive' ELSE 'sitov-card-ambiguous' END)),p.goals,n<>1 FROM public.path_nodes p CROSS JOIN generate_series(1,3)n WHERE p.source_id='sitov-61-n0';
