INSERT INTO public.path_nodes(id,unit_id,source_id,kind,sort_order,title,topic,merkkarte,goals,is_active) SELECT '00000000-0064-4000-8000-000000000011','00000000-0064-4000-8000-000000000010','sitov-card-foreign-node','practice',1,'Sitov Academy Paul',p.topic,jsonb_set(p.merkkarte,'{card}','"sitov-card-foreign"'),p.goals,true FROM public.path_nodes p WHERE p.source_id='sitov-61-n0';
CREATE FUNCTION pg_temp.sitov63_payload(p_key jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER AS $$
 SELECT jsonb_build_array(jsonb_build_object('id',old->'id','expected_hash',path_private.sitov_revision_hash(old),'after',candidate,'review',jsonb_build_object('approved',true,'reviewer','Sitov Academy synthetic reviewer','evidence_uri','catalog:synthetic-pointer','before_hash',path_private.sitov_revision_hash(old),'after_hash',path_private.sitov_revision_hash(candidate)))) FROM(SELECT old,jsonb_set(old,'{explanation_card}',p_key) candidate FROM(SELECT path_private.sitov_revision_projection('00000000-0061-4000-8000-000000000004') old)a)b;
$$;
GRANT EXECUTE ON FUNCTION pg_temp.sitov63_payload(jsonb) TO service_role;
CREATE TEMP TABLE sitov63_counts AS SELECT (SELECT count(*) FROM path_private.sitov_content_revisions) archives,(SELECT count(*) FROM path_private.sitov_content_revision_receipts) receipts;
SET LOCAL ROLE service_role;
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(''00000000-0064-4000-8000-000000000021'',pg_temp.sitov63_payload(''"sitov-card-missing"''))','sitov_revision_card_binding_invalid');
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(''00000000-0064-4000-8000-000000000022'',pg_temp.sitov63_payload(''"sitov-card-inactive"''))','sitov_revision_card_binding_invalid');
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(''00000000-0064-4000-8000-000000000023'',pg_temp.sitov63_payload(''"sitov-card-foreign"''))','sitov_revision_card_binding_invalid');
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(''00000000-0064-4000-8000-000000000024'',pg_temp.sitov63_payload(''"sitov-card-ambiguous"''))','sitov_revision_card_binding_invalid');
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(''00000000-0064-4000-8000-000000000025'',pg_temp.sitov63_payload(''null''))','sitov_revision_card_binding_invalid');
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(''00000000-0064-4000-8000-000000000026'',pg_temp.sitov63_payload(''""''))','sitov_revision_card_binding_invalid');
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(''00000000-0064-4000-8000-000000000027'',pg_temp.sitov63_payload(to_jsonb(repeat(''x'',101))))','sitov_revision_card_binding_invalid');
SELECT pg_temp.sitov61_error('SELECT public.sitov_revise_path_content(''00000000-0064-4000-8000-000000000028'',pg_temp.sitov63_payload(''17''))','sitov_revision_card_binding_invalid');
RESET ROLE;
SELECT pg_temp.sitov61_assert('card_all_invalid_source_exact',path_private.sitov_revision_full('00000000-0061-4000-8000-000000000004')=(SELECT full_row FROM sitov63_before));
SELECT pg_temp.sitov61_assert('card_all_invalid_archive_receipt_exact',(SELECT archives=(SELECT count(*) FROM path_private.sitov_content_revisions) AND receipts=(SELECT count(*) FROM path_private.sitov_content_revision_receipts) FROM sitov63_counts));
SET LOCAL ROLE service_role;
SELECT public.sitov_revise_path_content('00000000-0064-4000-8000-000000000030',pg_temp.sitov63_payload('"p1_greet"'));
RESET ROLE;
SELECT pg_temp.sitov61_assert('card_valid_current_binding',(SELECT explanation_card='p1_greet' FROM public.learning_exercises WHERE id='00000000-0061-4000-8000-000000000004'));
SELECT pg_temp.sitov61_assert('card_archived_old_new_full',(SELECT before_full#>>'{exercise,explanation_card}'='sitov-missing-old' AND after_full#>>'{exercise,explanation_card}'='p1_greet' AND before_projection->>'explanation_card'='sitov-missing-old' AND after_projection->>'explanation_card'='p1_greet' FROM path_private.sitov_content_revisions WHERE request_id='00000000-0064-4000-8000-000000000030'));
SELECT pg_temp.sitov61_assert('card_old_snapshots_exact',NOT EXISTS((SELECT row FROM sitov63_old_snapshots EXCEPT (SELECT to_jsonb(i) FROM path_private.practice_items i UNION ALL SELECT to_jsonb(i) FROM path_private.test_items i)) UNION ALL ((SELECT to_jsonb(i) FROM path_private.practice_items i UNION ALL SELECT to_jsonb(i) FROM path_private.test_items i) EXCEPT SELECT row FROM sitov63_old_snapshots)));
SELECT pg_temp.sitov62_deferred('UPDATE public.learning_exercises SET explanation_card=''other'' WHERE id=''00000000-0061-4000-8000-000000000004''');
SELECT pg_temp.sitov61_assert('card_direct_update_blocked',true);
-- Deactivate synthetic empty auxiliary practice cards before exporting a valid pool.
UPDATE public.path_nodes SET is_active=false WHERE source_id LIKE 'sitov-card-case-%';
SELECT set_config('request.jwt.claim.sub','00000000-0062-4000-8000-000000000002',true);
INSERT INTO public.path_node_translations(node_id,locale,title) SELECT '00000000-0063-4000-8000-000000000001',lang,'Sitov Academy Paul' FROM unnest(ARRAY['de','en','ru','uk','tr']) lang;
CREATE TEMP TABLE sitov63_export AS SELECT public.export_learning_path((SELECT unit_id FROM public.learning_exercises WHERE id='00000000-0061-4000-8000-000000000004')) seed;
SELECT pg_temp.sitov61_assert('card_export_valid_shape',(SELECT path_private.valid_seed_shape(seed) FROM sitov63_export));
SELECT path_private.import_path_catalog(seed,NULL) FROM sitov63_export;
SELECT pg_temp.sitov61_assert('card_new_pointer_import_accepted',true);
CREATE FUNCTION pg_temp.sitov63_stale_seed(p_seed jsonb) RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_set(p_seed,'{nodes}',(SELECT jsonb_agg(n||jsonb_build_object('exercises',(SELECT jsonb_agg(e||CASE WHEN e->>'id'='00000000-0061-4000-8000-000000000004' THEN jsonb_build_object('explanation_card','sitov-missing-old') ELSE '{}'::jsonb END) FROM jsonb_array_elements(n->'exercises') e))) FROM jsonb_array_elements(p_seed->'nodes')n));$$;
SELECT pg_temp.sitov61_error('SELECT path_private.import_path_catalog('||quote_literal(pg_temp.sitov63_stale_seed(seed))||'::jsonb,NULL)','sitov_revision_import_conflict') FROM sitov63_export;
SELECT pg_temp.sitov61_assert('card_stale_pointer_import_blocked',true);
